  expmapX0: f32,
  expmapY0: f32,
  expmapAngularSamples: f32,
  expmapRhoStep: f32,
  expmapTailStep: f32,
  expmapTailIntervals: f32,
  expmapDensity: f32,
  expmapCenterHalf: f32,
