  aspect: f32,
  angle: f32,
  clearHistory: f32,
  shiftTexX: f32,
  shiftTexY: f32,
  dispatchOriginX: f32,
  dispatchOriginY: f32,
  copyLayerCount: f32,
  mu: f32,
  workCounterShift: f32,
  rawOriginX: f32,
