  candidate.orbitGradient = clamp(
    textureLoad(orbitGradientTex, coord, 0) / max(zoomFactor, 1e-30),
    vec4<f32>(-DISPLAY_STORAGE_MAX),
    vec4<f32>(DISPLAY_STORAGE_MAX),
  );
